Here's a command file in that style. Save it as `src/commands/pace.js`:

js
const { SlashCommandBuilder } = require('discord.js');

const KM_PER_MILE = 1.609344;

function parseTime(str) {
  const parts = str.trim().split(':').map(Number);
  if (parts.length < 2 || parts.length > 3) return null;
  if (parts.some(n => !Number.isFinite(n) || n < 0)) return null;
  return parts.reduce((acc, n) => acc * 60 + n, 0);
}

function formatPace(sec) {
  let m = Math.floor(sec / 60);
  let s = Math.round(sec % 60);
  if (s === 60) { m += 1; s = 0; }
  return `${m}:${String(s).padStart(2, '0')}`;
}

module.exports = {
  data: new SlashCommandBuilder()
    .setName('pace')
    .setDescription('Convert a finish time and distance into min/mile pace')
    .addStringOption(o => o.setName('time').setDescription('Finish time, e.g. 25:30 or 1:52:10').setRequired(true))
    .addNumberOption(o => o.setName('distance').setDescription('Distance').setRequired(true).setMinValue(0.1))
    .addStringOption(o => o.setName('unit').setDescription('mi or km (default mi)')
      .addChoices({ name: 'miles', value: 'mi' }, { name: 'kilometers', value: 'km' })),
  async execute(interaction) {
    const total = parseTime(interaction.options.getString('time'));
    if (total === null || total === 0) {
      return interaction.reply({ content: 'Use a time like `25:30` or `1:52:10`.', ephemeral: true });
    }
    const dist = interaction.options.getNumber('distance');
    const unit = interaction.options.getString('unit') ?? 'mi';
    const miles = unit === 'km' ? dist / KM_PER_MILE : dist;
    await interaction.reply(`${dist} ${unit} in ${interaction.options.getString('time')} is **${formatPace(total / miles)} /mi**`);
  },
};

